// Auto-setup for TowerInstallBase package.
// 1) If the prefab's mesh reference is missing, bakes TowerInstallBase_Mesh.asset and assigns it.
// 2) If the project uses URP/HDRP, switches the two materials to the pipeline's default Lit shader.
#if UNITY_EDITOR
using UnityEditor;
using UnityEngine;
using UnityEngine.Rendering;

[InitializeOnLoad]
public static class TowerInstallBaseSetup
{
    const string Root = "Assets/TowerInstallBase/";
    const string PrefabPath = Root + "Prefabs/TowerInstallBase.prefab";
    const string MeshAssetPath = Root + "Meshes/TowerInstallBase_Mesh.asset";

    static TowerInstallBaseSetup() { EditorApplication.delayCall += Run; }

    [MenuItem("Tools/TowerInstallBase/Re-run Setup")]
    public static void Run()
    {
        if (!System.IO.File.Exists(PrefabPath)) return;
        FixMaterials();
        FixMesh();
    }

    static void FixMaterials()
    {
        var rp = GraphicsSettings.currentRenderPipeline;
        if (rp == null || rp.defaultShader == null) return;
        foreach (var name in new[] { "TowerInstallBase_Body", "TowerInstallBase_Stripe" })
        {
            var m = AssetDatabase.LoadAssetAtPath<Material>(Root + "Materials/" + name + ".mat");
            if (m == null || m.shader == rp.defaultShader || m.shader.name != "Standard") continue;
            Color c = m.GetColor("_Color");
            m.shader = rp.defaultShader;
            if (m.HasProperty("_BaseColor")) m.SetColor("_BaseColor", c);
            if (m.HasProperty("_Smoothness")) m.SetFloat("_Smoothness", name.EndsWith("Body") ? 0.25f : 0.5f);
            EditorUtility.SetDirty(m);
        }
        AssetDatabase.SaveAssets();
    }

    static void FixMesh()
    {
        var root = PrefabUtility.LoadPrefabContents(PrefabPath);
        try
        {
            var mf = root.GetComponent<MeshFilter>();
            if (mf == null || mf.sharedMesh != null) return;
            var mesh = AssetDatabase.LoadAssetAtPath<Mesh>(MeshAssetPath);
            if (mesh == null)
            {
                mesh = BuildMesh();
                AssetDatabase.CreateAsset(mesh, MeshAssetPath);
            }
            mf.sharedMesh = mesh;
            PrefabUtility.SaveAsPrefabAsset(root, PrefabPath);
            Debug.Log("[TowerInstallBase] Mesh asset baked and assigned to prefab.");
        }
        finally { PrefabUtility.UnloadPrefabContents(root); }
    }

    public static Mesh BuildMesh()
    {
        var m = new Mesh { name = "TowerInstallBase_Mesh" };
        var v = new Vector3[544]; var n = new Vector3[544]; var uv = new Vector2[544];
        for (int i = 0; i < v.Length; i++)
        {
            v[i] = new Vector3(P[i * 3], P[i * 3 + 1], P[i * 3 + 2]);
            n[i] = new Vector3(N[i * 3], N[i * 3 + 1], N[i * 3 + 2]);
            uv[i] = new Vector2(U[i * 2], U[i * 2 + 1]);
        }
        m.vertices = v; m.normals = n; m.uv = uv;
        m.subMeshCount = 2;
        m.SetTriangles(T0, 0); m.SetTriangles(T1, 1);
        m.RecalculateBounds(); m.RecalculateTangents();
        return m;
    }

